const fs=require('fs'),path=require('path'),cp=require('child_process');
const {chromium}=require('@playwright/test');
const TARGET='assets/css/components/ai/doke-ai-assistant.css';
const IMPORTER='assets/css/pages/pedidos-runtime-operations.css';
const RUNTIME='assets/js/pages/pedidos/orders-ai-assistant.js';
const PAGE='pedidos.html';
const SHA=process.env.TARGET_SHA,TARGET_BLOB=process.env.TARGET_BLOB,IMPORTER_BLOB=process.env.IMPORTER_BLOB,RUNTIME_BLOB=process.env.RUNTIME_BLOB;
const VIEWPORTS=[359,430,759,760,761,1024,1280,1440];
const AFFECTED='body.orders-page-shell .doke-ai-panel';
const sh=c=>cp.execSync(c,{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();
const assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
function importsFor(file,tracked){const src=fs.readFileSync(file,'utf8'),out=[],re=/@import\s+(?:url\()?['"]?([^'"\);]+\.css(?:\?[^'"\)]*)?)['"]?\)?/gi;let m;while((m=re.exec(src))){let v=m[1].replace(/\?.*$/,'').replace(/^\.\//,'');if(v.startsWith('/'))v=v.replace(/^\/+/, '');else if(!v.startsWith('assets/'))v=path.posix.normalize(path.posix.join(path.posix.dirname(file),v));if(tracked.has(v))out.push(v)}return out}
function verifyStatic(){assert(sh('git rev-parse HEAD')===SHA,'wrong HEAD');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'target blob drift');assert(sh(`git hash-object ${IMPORTER}`)===IMPORTER_BLOB,'importer blob drift');assert(sh(`git hash-object ${RUNTIME}`)===RUNTIME_BLOB,'runtime blob drift');const html=fs.readFileSync(PAGE,'utf8'),runtime=fs.readFileSync(RUNTIME,'utf8');assert(html.includes('assets/js/pages/pedidos/orders-ai-assistant.js'),'runtime script missing from pedidos.html');assert(html.includes('orders-page-shell'),'orders shell missing');assert(runtime.includes("className = 'doke-ai-layer'")&&runtime.includes('<section class="doke-ai-panel"'),'runtime DOM authority drift');assert(runtime.includes('const open = () =>')&&runtime.includes("layer.classList.add('is-open')"),'runtime open-state authority drift');const report=JSON.parse(fs.readFileSync('reports/generated/active-legacy-structures-report.json','utf8')),tracked=new Set(sh('git ls-files -z assets/css').split('\0').filter(f=>f.endsWith('.css'))),direct=[...tracked].filter(f=>importsFor(f,tracked).includes(TARGET)).sort();assert(JSON.stringify(direct)===JSON.stringify([IMPORTER]),`direct importer drift ${JSON.stringify(direct)}`);const reached=[];for(const p of report.pageAssets){const seen=new Set(),todo=[...(p.css||[]).filter(f=>tracked.has(f))];let hit=false;while(todo.length){const f=todo.pop();if(seen.has(f)||!tracked.has(f))continue;seen.add(f);if(f===TARGET){hit=true;break}for(const n of importsFor(f,tracked))todo.push(n)}if(hit)reached.push(p.page)}reached.sort();assert(JSON.stringify(reached)===JSON.stringify([PAGE]),`active reach drift ${JSON.stringify(reached)}`);console.log(`REACH AUTHORITY PASS|page=${PAGE}|directImporter=${IMPORTER}|runtimeAuthority=${RUNTIME}|target=${TARGET}|affectedFamilies=1`)}
function verifyDead(){const p=parse(fs.readFileSync(TARGET,'utf8'));assert(p.declarations.length===274&&p.dead.length===1,`target parse drift ${p.declarations.length}/${p.dead.length}`);const d=p.dead[0];assert(d.line===396,`dead line drift ${d.line}`);assert(d.selector===AFFECTED,'selector drift');assert(d.property==='height','property drift');assert(d.value==='min(88dvh, 760px)','dead value drift');assert(d.context==='@media (max-width: 760px)',`context drift ${d.context}`);assert(d.winnerLine===412&&d.winnerValue==='min(86dvh, 720px)',`winner drift ${d.winnerLine}/${d.winnerValue}`);assert(!d.important&&!d.winnerImportant,'important drift');console.log('STATIC CASCADE PASS|decl=274|dead=1|families=1|identical=0|changed=1|context=max760|line=396|winnerLine=412') ;return p}
function removeDead(p){const src=fs.readFileSync(TARGET,'utf8'),nl=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(nl&&lines.at(-1)==='')lines.pop();const d=p.dead[0];assert(lines[d.line-1]?.trim()==='height: min(88dvh, 760px);','source line drift');lines.splice(d.line-1,1);fs.writeFileSync(TARGET,lines.join('\n')+(nl?'\n':''));const after=parse(fs.readFileSync(TARGET,'utf8')),stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(after.declarations.length===273&&after.dead.length===0,`after parse drift ${after.declarations.length}/${after.dead.length}`);assert(stat[0]==='0'&&stat[1]==='1'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);console.log('R1 REMOVE PASS|decl=274->273|dead=1->0|additions=0|deletions=1')}
async function prepare(page){await page.evaluate(()=>{document.querySelector('[data-doke-document-preloader]')?.remove();document.documentElement.classList.remove('doke-mobile-shell-pending');const s=document.createElement('style');s.setAttribute('data-ux050-freeze','');s.textContent='*,*::before,*::after{transition-duration:0s!important;transition-delay:0s!important;animation-duration:0s!important;animation-delay:0s!important}';document.head.appendChild(s)});await page.waitForFunction(()=>window.DokeOrders?.aiAssistant&&document.querySelector('.doke-ai-panel'),null,{timeout:5000})}
async function snap(page,width,state){return page.evaluate(({width,state,AFFECTED})=>{const el=document.querySelector(AFFECTED);if(!el)throw new Error('panel missing');const s=getComputedStyle(el),r=el.getBoundingClientRect(),layer=document.querySelector('[data-doke-ai-layer]'),round=n=>Math.round(n*1000)/1000;return{width,state,layerHidden:!!layer?.hidden,layerOpen:!!layer?.classList.contains('is-open'),style:{display:s.display,position:s.position,width:s.width,height:s.height,minHeight:s.minHeight,maxHeight:s.maxHeight,borderLeftWidth:s.borderLeftWidth,borderTopWidth:s.borderTopWidth,borderTopLeftRadius:s.borderTopLeftRadius,borderTopRightRadius:s.borderTopRightRadius,transform:s.transform,opacity:s.opacity,overflowX:s.overflowX,overflowY:s.overflowY},rect:[round(r.x),round(r.y),round(r.width),round(r.height)],panelScroll:[el.scrollWidth,el.scrollHeight,el.clientWidth,el.clientHeight],doc:[document.documentElement.clientWidth,document.documentElement.scrollWidth,document.body.scrollWidth]};},{width,state,AFFECTED})}
async function capture(browser,tag){const out={},overflow=0;let over=0;for(const width of VIEWPORTS){const ctx=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),page=await ctx.newPage();await page.route('**/*',route=>{const u=new URL(route.request().url()),local=u.origin==='http://127.0.0.1:4173';if(!local)return route.abort();if(u.pathname.endsWith('.js')&&!u.pathname.endsWith('/assets/js/pages/pedidos/orders-ai-assistant.js'))return route.abort();return route.continue()});await page.goto(`http://127.0.0.1:4173/${PAGE}?ux050-${tag}-${width}`,{waitUntil:'domcontentloaded',timeout:20000});await prepare(page);const closed=await snap(page,width,'closed');await page.evaluate(()=>window.DokeOrders.aiAssistant.open());await page.waitForTimeout(30);const open=await snap(page,width,'open');assert(open.layerHidden===false&&open.layerOpen===true,`open state drift ${width}`);assert(closed.layerHidden===true,`closed state drift ${width}`);if(open.doc[1]>open.doc[0]+1||open.doc[2]>open.doc[0]+1)over++;out[String(width)]={closed,open};await ctx.close()}console.log(`R1 BROWSER CAPTURE|tag=${tag}|page=${PAGE}|states=2|viewports=${VIEWPORTS.join(',')}|samples=${VIEWPORTS.length*2}|horizontalOverflowSamples=${over}`);return{out,over}}
(async()=>{assert(SHA&&TARGET_BLOB&&IMPORTER_BLOB&&RUNTIME_BLOB,'missing env');verifyStatic();const parsed=verifyDead();const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{const before=await capture(browser,'before');removeDead(parsed);const after=await capture(browser,'after');assert(before.over===after.over,`overflow parity drift ${before.over}/${after.over}`);assert(JSON.stringify(before.out)===JSON.stringify(after.out),'runtime parity mismatch');console.log(`R1 BROWSER PASS|page=${PAGE}|states=closed+open|viewports=${VIEWPORTS.length}|before=${VIEWPORTS.length*2}|after=${VIEWPORTS.length*2}|runtimeDiffs=0|overflowParity=${before.over}->${after.over}|family=1/1|criticalBoundary=759/760/761`)}finally{await browser.close()}}finally{server.kill('SIGTERM')}sh(`git reset --hard ${SHA}`);sh('git clean -fdx');assert(sh('git rev-parse HEAD')===SHA&&sh(`git hash-object ${TARGET}`)===TARGET_BLOB&&sh('git status --porcelain')==='','restore drift');console.log(`R1 CHECKPOINT PASS|sha=${SHA}|productMutation=0|issueCreated=0|prCreated=0`)})().catch(e=>{console.error(e.stack||e);process.exit(1)});
